'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const psl = require('../extension/core/psl');
const gen = require('../scripts/gen-psl');

test('registrable domain: plain and multi-label suffixes', () => {
  assert.equal(psl.registrableDomain('www.cnn.com'), 'cnn.com');
  assert.equal(psl.registrableDomain('cnn.com'), 'cnn.com');
  assert.equal(psl.registrableDomain('www.wbdprivacy.com'), 'wbdprivacy.com');
  assert.equal(psl.registrableDomain('x.co.uk'), 'x.co.uk');
  assert.equal(psl.registrableDomain('www.x.co.uk'), 'x.co.uk');
  assert.equal(psl.registrableDomain('a.b.x.co.uk'), 'x.co.uk');
  assert.equal(psl.registrableDomain('www.bbc.co.uk'), 'bbc.co.uk');
  assert.equal(psl.registrableDomain('co.uk'), null, 'a bare public suffix has no registrable domain');
  assert.equal(psl.registrableDomain('uk'), null);
  assert.equal(psl.registrableDomain('foo.example.com.au'), 'example.com.au');
});
test('private-section suffixes: a.github.io and b.github.io are different owners', () => {
  assert.equal(psl.registrableDomain('a.github.io'), 'a.github.io');
  assert.equal(psl.registrableDomain('www.a.github.io'), 'a.github.io');
  assert.equal(psl.registrableDomain('github.io'), null);
  assert.equal(psl.sameOwner('a.github.io', 'b.github.io'), false);
  assert.equal(psl.sameOwner('www.a.github.io', 'docs.a.github.io'), true);
  assert.equal(psl.sameOwner('foo.blogspot.com', 'bar.blogspot.com'), false);
  assert.equal(psl.sameOwner('github.com', 'docs.github.com'), true);
});
test('co.uk is handled: x.co.uk and y.co.uk are different owners, www.x.co.uk and x.co.uk the same', () => {
  assert.equal(psl.sameOwner('x.co.uk', 'y.co.uk'), false);
  assert.equal(psl.sameOwner('www.x.co.uk', 'x.co.uk'), true);
  assert.equal(psl.sameOwner('a.co.uk', 'b.co.uk'), false);
});
test('wildcard and exception rules (*.ck, !www.ck)', () => {
  assert.equal(psl.registrableDomain('foo.bar.ck'), 'foo.bar.ck'); // bar.ck is a suffix via *.ck
  assert.equal(psl.registrableDomain('bar.ck'), null);
  assert.equal(psl.registrableDomain('www.ck'), 'www.ck'); // exception: www.ck is registrable
  assert.equal(psl.registrableDomain('a.www.ck'), 'www.ck');
});
test('unknown TLDs use the default rule, case/port/trailing dot are tolerated, IPs have no owner', () => {
  assert.equal(psl.registrableDomain('a.b.invalidtld'), 'b.invalidtld');
  assert.equal(psl.registrableDomain('WWW.CNN.COM.'), 'cnn.com');
  assert.equal(psl.registrableDomain('www.cnn.com:8443'), 'cnn.com');
  assert.equal(psl.registrableDomain('127.0.0.1'), null);
  assert.equal(psl.registrableDomain(''), null);
  assert.equal(psl.registrableDomain(undefined), null);
  assert.equal(psl.registrableDomain('a..com'), null);
  assert.equal(psl.registrableDomain('xn--bcher-kva.example'), 'xn--bcher-kva.example'); // punycode names work
});
test('known policy services include their subdomains, and nothing that merely ends the same way', () => {
  for (const h of ['onetrust.com', 'privacy.onetrust.com', 'a.b.trustarc.com', 'www.termly.io', 'iubenda.com', 'www.iubenda.com']) assert.equal(psl.isKnownPolicyService(h), true, h);
  for (const h of ['notonetrust.com', 'onetrust.com.evil.example', 'termly.io.example', 'example.com']) assert.equal(psl.isKnownPolicyService(h), false, h);
});
test('unrelatedPolicyHost: different owner and not a policy service', () => {
  assert.equal(psl.unrelatedPolicyHost('www.cnn.com', 'www.wbdprivacy.com'), true);
  assert.equal(psl.unrelatedPolicyHost('www.cnn.com', 'edition.cnn.com'), false);
  assert.equal(psl.unrelatedPolicyHost('www.cnn.com', 'privacy.onetrust.com'), false);
  assert.equal(psl.unrelatedPolicyHost('a.github.io', 'b.github.io'), true);
  assert.equal(psl.unrelatedPolicyHost('www.x.co.uk', 'y.co.uk'), true);
  assert.equal(psl.unrelatedPolicyHost('www.x.co.uk', 'legal.x.co.uk'), false);
  assert.equal(psl.unrelatedPolicyHost('', 'example.com'), false, 'no page host: cannot tell, so no accusation');
});
test('bundled data: generated file is intact (both sections, punycode, header) and the generator packs/parses correctly', () => {
  const file = fs.readFileSync(path.join(__dirname, '..', 'extension', 'core', 'psl-data.js'), 'utf8');
  assert.match(file, /GENERATED by scripts\/gen-psl\.js/);
  assert.match(file, /Mozilla Public License/);
  const data = require('../extension/core/psl-data');
  assert.ok(data.count > 9000, 'ICANN + private rules present, got ' + data.count);
  assert.match(data.version, /^\d{4}-\d\d-\d\d_/);
  assert.ok(/\ngithub\t|\bio\t/.test('\n' + data.packed), 'io group present');
  // the extension never fetches the list at run time
  const mod = fs.readFileSync(path.join(__dirname, '..', 'extension', 'core', 'psl.js'), 'utf8');
  assert.doesNotMatch(mod, /fetch\(|XMLHttpRequest|chrome\.|browser\./);
  const parsed = gen.parse('// VERSION: v\n// COMMIT: c\ncom\n*.ck\n!www.ck\nco.uk\n// comment\n公司.cn\n');
  assert.deepEqual(parsed.rules, ['com', '*.ck', '!www.ck', 'co.uk', 'xn--55qx5d.cn']);
  assert.equal(gen.pack(['com', 'co.uk', 'uk', '*.ck', '!www.ck']), 'ck\t*.@ !www\ncom\t@\nuk\tco @');
});
